local MonstranceMaker = {}
local PRODUCTS = {
    brass_monstrance = { name = "Medeninasta monstranca", brassCost = 2, glassCost = 1, time = 4, cost = 80, sanctity = 6, prestige = 2, description = "Medeninasta monstranca z lunulo." },
    silver_monstrance = { name = "Srebrna monstranca", silverCost = 2, glassCost = 1, time = 6, cost = 220, sanctity = 10, prestige = 5, happiness = 1, description = "Srebrna monstranca z razgledom na hostijo." },
    gold_monstrance = { name = "Zlata monstranca", goldCost = 1, silverCost = 1, glassCost = 1, time = 8, cost = 520, sanctity = 15, prestige = 12, happiness = 2, description = "Zlata monstranca za slovesno adoracijo." },
    rayed_monstrance = { name = "Žarki monstranca", goldCost = 2, silverCost = 1, glassCost = 1, time = 10, cost = 980, sanctity = 19, prestige = 20, happiness = 4, description = "Monstranca z zlatimi žarki okoli lunule." },
    jewel_monstrance = { name = "Draguljna monstranca", goldCost = 2, silverCost = 1, jewelCost = 2, glassCost = 1, time = 12, cost = 1700, sanctity = 24, prestige = 32, happiness = 6, description = "Monstranca z dragulji za katedralo." },
    royal_shrine_monstrance = { name = "Kraljevski svetiščna monstranca", goldCost = 4, silverCost = 2, jewelCost = 4, pearlCost = 2, glassCost = 2, time = 18, cost = 3800, sanctity = 40, prestige = 75, happiness = 15, description = "Veliki kraljevski svetiščna monstranca z dragulji in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Monstrančarska delavnica", cost = { gold = 300, wood = 130 }, upkeep = 8, qualityBonus = 5 },
    forge = { name = "Monstrančarska kovačija", cost = { gold = 950, wood = 220, stone = 200, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    crystal_room = { name = "Kristalna soba", cost = { gold = 2000, wood = 300, stone = 400, glass = 8, silver = 25 }, upkeep = 48, qualityBonus = 30 },
    royal_monstrance_atelier = { name = "Kraljevski atelje monstranc", cost = { gold = 8000, wood = 600, stone = 800, gold = 80, jewel = 25 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 35 },
}
MonstranceMaker.brassStock = 10; MonstranceMaker.silverStock = 8; MonstranceMaker.goldStock = 8; MonstranceMaker.glassStock = 10; MonstranceMaker.jewelStock = 6; MonstranceMaker.pearlStock = 4
MonstranceMaker.productStock = {}; MonstranceMaker.buildings = {}; MonstranceMaker.maker = nil; MonstranceMaker.activeMaking = {}; MonstranceMaker.totalProducts = 0; MonstranceMaker.dayTimer = 0
function MonstranceMaker.init() MonstranceMaker.brassStock=10; MonstranceMaker.silverStock=8; MonstranceMaker.goldStock=8; MonstranceMaker.glassStock=10; MonstranceMaker.jewelStock=6; MonstranceMaker.pearlStock=4; MonstranceMaker.productStock={}; MonstranceMaker.buildings={}; MonstranceMaker.maker=nil; MonstranceMaker.activeMaking={}; MonstranceMaker.totalProducts=0; MonstranceMaker.dayTimer=0; print("[MonstranceMaker] Royal Monstrance Maker System initialized (6 products, 4 buildings)") end
function MonstranceMaker.hireMaker(n,s) s=s or math.random(50,90); local c=510+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MonstranceMaker.maker={name=n or ("Monstrančar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Monstrančar najet: %s (spretnost: %d)",MonstranceMaker.maker.name,s),"success") end; return true end
function MonstranceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MonstranceMaker.build(id) local ok,e=MonstranceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MonstranceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MonstranceMaker.getQualityBonus() local b=0; for _,bd in ipairs(MonstranceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MonstranceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brassCost and MonstranceMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and MonstranceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MonstranceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.glassCost and MonstranceMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.jewelCost and MonstranceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MonstranceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MonstranceMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MonstranceMaker.maker then return false,"Potreben monstrančar" end; return true end
function MonstranceMaker.make(pt,qty) qty=qty or 1; local ok,e=MonstranceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brassCost then MonstranceMaker.brassStock=MonstranceMaker.brassStock-d.brassCost*qty end; if d.silverCost then MonstranceMaker.silverStock=MonstranceMaker.silverStock-d.silverCost*qty end; if d.goldCost then MonstranceMaker.goldStock=MonstranceMaker.goldStock-d.goldCost*qty end; if d.glassCost then MonstranceMaker.glassStock=MonstranceMaker.glassStock-d.glassCost*qty end; if d.jewelCost then MonstranceMaker.jewelStock=MonstranceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MonstranceMaker.pearlStock=MonstranceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MonstranceMaker.maker then t=math.max(1,t-math.floor(MonstranceMaker.maker.skill/12)) end; table.insert(MonstranceMaker.activeMaking,{id="monstrance_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sanctity=d.sanctity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MonstranceMaker.completeMaking(m) local q=1.0+(MonstranceMaker.getQualityBonus()/100); if MonstranceMaker.maker then q=q+(MonstranceMaker.maker.skill/180) end; q=math.min(2.0,q); MonstranceMaker.productStock[m.productType]=(MonstranceMaker.productStock[m.productType] or 0)+m.quantity; MonstranceMaker.totalProducts=MonstranceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MonstranceMaker.maker then MonstranceMaker.maker.itemsMade=MonstranceMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then MonstranceMaker.maker.skill=math.min(100,MonstranceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Monstranca izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"monstrance.completed",{productName=m.productName,sanctity=m.sanctity}) end end
function MonstranceMaker.update(dt) if not _G.state then return end; MonstranceMaker.dayTimer=MonstranceMaker.dayTimer+dt; if MonstranceMaker.dayTimer>=30 then MonstranceMaker.dayTimer=0; for i=#MonstranceMaker.activeMaking,1,-1 do local m=MonstranceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MonstranceMaker.completeMaking(m); table.remove(MonstranceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MonstranceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MonstranceMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MonstranceMaker.getStats() return {brassStock=MonstranceMaker.brassStock,silverStock=MonstranceMaker.silverStock,goldStock=MonstranceMaker.goldStock,glassStock=MonstranceMaker.glassStock,jewelStock=MonstranceMaker.jewelStock,pearlStock=MonstranceMaker.pearlStock,productStock=MonstranceMaker.productStock,numBuildings=#MonstranceMaker.buildings,hasMaker=MonstranceMaker.maker~=nil,makerName=MonstranceMaker.maker and MonstranceMaker.maker.name or "—",makerSkill=MonstranceMaker.maker and MonstranceMaker.maker.skill or 0,activeMaking=#MonstranceMaker.activeMaking,totalProducts=MonstranceMaker.totalProducts} end
return MonstranceMaker
